head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > E > onviewchange]<br/>컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "ref 속성으로 바인딩된 DataCollection 에 의해 입력값이 변경되면 onviewchange 이벤트는 발생하지 않습니다.",        
    ]
}


scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }

    let properties = {
        ref : "data:dlt_ref.label",
    }

    let cList = $c.gcm.createCList(properties);  
    let eList = $c.gcm.createEList(["onviewchange"]);

    // comp 생성 함수 호출
    let grp_comp = $c.gcm.getTestGroup();
    let strDltRef = '';
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $p.data.remove("dlt_ref");

    strDltRef += '<w2:dataList baseNode="list" repeatNode="map" id="dlt_ref">';
    strDltRef += '<w2:columnInfo>';
    strDltRef += '<w2:column id="label" name="name1" dataType="text"></w2:column>';
    strDltRef += '<w2:column id="value" name="name2" dataType="text"></w2:column>';
    strDltRef += '</w2:columnInfo>';
    strDltRef += '<w2:data use="true">';
    strDltRef += '<w2:row>';
    strDltRef += '<label><![CDATA[20251101]]></label>';
    strDltRef += '<value><![CDATA[1]]></value>';
    strDltRef += '</w2:row>';
    strDltRef += '<w2:row>';
    strDltRef += '<label><![CDATA[20251130]]></label>';
    strDltRef += '<value><![CDATA[2]]></value>';
    strDltRef += '</w2:row>';
    strDltRef += '<w2:row>';
    strDltRef += '<label><![CDATA[20251130]]></label>';
    strDltRef += '<value><![CDATA[3]]></value>';
    strDltRef += '</w2:row>';
    strDltRef += '</w2:data>';
    strDltRef += '</w2:dataList>';

    $p.data.create(strDltRef);

    strTarget += '<w2:inputCalendar ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:150px; height:23px; " calendarValueType="yearMonthDate"></w2:inputCalendar>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "inputCalendar",
        strTarget,
        grp_comp
    );    

    strGridView += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_ref" id="gridView1" style="width: 500px;height: 200px;">';
    strGridView += '<w2:caption id="caption1" style="" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header id="header1" style="">';
    strGridView += '<w2:row id="row1" style="">';
    strGridView += '<w2:column width="140" inputType="text" style="" id="column1" value="name1"></w2:column>';
    strGridView += '<w2:column width="136" inputType="text" style="" id="column3" value="name2" displayMode="label"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody id="gBody1" style="">';
    strGridView += '<w2:row id="row2" style="">';
    strGridView += '<w2:column width="140" inputType="text" style="" id="label" value=""></w2:column>';
    strGridView += '<w2:column width="136" inputType="text" style="" id="value" value="" displayMode="label"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';

    // target 생성
    scwin.gridView1 = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}
